 'F': lambda p: -p[0]*(eps**p[1])*np.exp(-p[2]*eps)*(1+p[3]*T)+p[4]+p[5]*T,
 'G': lambda p: -p[0]*np.exp(-p[1]*eps)*(1+p[2]*T)-p[3]*np.exp(-p[4]*T)+p[5]*eps,
}
